def wrap(text, width):
    lines = []
    for para in text.split('\n'):
        words = para.split()
        pieces = []
        for w in words:
            if len(w) > width:
                for i in range(0, len(w), width):
                    pieces.append(w[i:i+width])
            else:
                pieces.append(w)
        if not pieces:
            lines.append('')
            continue
        cur = []
        cur_len = 0
        for p in pieces:
            if not cur:
                cur = [p]
                cur_len = len(p)
            elif cur_len + 1 + len(p) <= width:
                cur.append(p)
                cur_len += 1 + len(p)
            else:
                lines.append(' '.join(cur))
                cur = [p]
                cur_len = len(p)
        if cur:
            lines.append(' '.join(cur))
    return lines

